        whyEn: "When should you put a key on a Suspense boundary?",
        ideas: [{ labelUk: "новий запит", labelEn: "new query", anyOf: ["запит", "query", "скид", "reset", "ключ", "key"] }, { labelUk: "свіжий fallback", labelEn: "fresh fallback", anyOf: ["fallback", "свіж", "fresh", "монт", "remount"] }, { labelUk: "стан форм", labelEn: "form state", anyOf: ["форм", "form", "стан", "state"] }],
